8053 func (gs *GameState) ProcessTriggeredAbilities(event *Event) {
8054 	if gs.EventBus == nil {
8055 		return
8056 	}
8057 
8058 	// Combat damage-to-permanent events carry their dealer in Source but,
8059 	// unlike noncombat CreateDamageEvent callers, omit Player. Normalize the
8060 	// dealer controller so ordinary source-controller damage triggers retain
8061 	// their existing combat behavior.
8062 	if event != nil && event.Type == EventDamageDealt &&
8063 		event.Player < 0 && event.Source != nil {
8064 		event.Player = event.Source.Controller
8065 	}
8066 
8067 	triggered := gs.EventBus.Publish(event)
8068 	for _, ability := range triggered {
8069 		if event != nil && event.Type == EventDamageDealt &&
8070 			ability.EffectValue["receiver_permanent_type"] == "creature" &&
8071 			(event.Target == nil || !event.Target.IsCreature()) {
8072 			continue
8073 		}
8074 		if event != nil && event.Type == EventPlayerDamaged &&
8075 			ability.EffectValue["noncombat_damage_only"] == true &&
8076 			event.Data["is_combat"] == true {
8077 			continue
8078 		}
8079 		gs.PutTriggeredAbilityOnStackWithEvent(ability, event)
8080 	}
8081 
8082 	// Granted triggered abilities ([VOCAB] #2404): synthesize re-sourced
8083 	// copies from every active filtered grant (see triggered_grants.go).
8084 	gs.processFilteredTriggeredGrants(event)
8085 }

